import math
from collections import defaultdict

def prime_factorization(n):
    factors = defaultdict(int)
    d = 2
    temp = n
    while d * d <= temp:
        while temp % d == 0:
            factors[d] += 1
            temp //= d
        d += 1
    if temp > 1:
        factors[temp] += 1
    return factors

def euler_phi(n):
    if n == 1:
        return 1
    factors = prime_factorization(n)
    result = n
    for p in factors:
        result = result * (p - 1) // p
    return result

def multiplicative_order(a, n):
    if math.gcd(a, n) != 1:
        return 0

    phi_n = euler_phi(n)

    # Find divisors of phi_n
    divisors = []
    for i in range(1, int(math.sqrt(phi_n)) + 1):
        if phi_n % i == 0:
            divisors.append(i)
            if i*i != phi_n:
                divisors.append(phi_n // i)
    divisors.sort()

    for d in divisors:
        if pow(a, d, n) == 1:
            return d
    return phi_n

def count_cycles(m):
    if m <= 1 or m % 3 == 0:
        return None

    divisors = []
    for i in range(1, int(math.sqrt(m)) + 1):
        if m % i == 0:
            divisors.append(i)
            if i * i != m:
                divisors.append(m // i)

    total_cycles = 0

    # k ranges over all divisors of m such that k > 1
    for k in divisors:
