import math

def phi(n):
    """Calculates Euler's totient function phi(n)."""
    result = n
    p = 2
    while p * p <= n:
        if n % p == 0:
            while n % p == 0:
                n //= p
            result -= result // p
        p += 1
    if n > 1:
        result -= result // n
    return result

def get_divisors(n):
    """Returns a sorted list of all divisors of n."""
    divs = set()
    for i in range(1, int(math.sqrt(n)) + 1):
        if n % i == 0:
            divs.add(i)
            divs.add(n // i)
    return sorted(list(divs))

def get_order(a, n):
    """Calculates the multiplicative order of a modulo n."""
    if math.gcd(a, n) != 1:
        # Should not happen given constraints, but necessary for robustness
        return None 

    phi_n = phi(n)

    # Potential orders must divide phi(n)
    potential_orders = get_divisors(phi_n)

    for L in potential_orders:
        if pow(a, L, n) == 1:
            return L
    return phi_n # Should be found within divisors

def C(m):
    """Calculates the number of cycles C(m) for the permutation x -> 3x mod m."""
    if m <= 1 or m % 3 == 0:
        return None

    divisors = []
    for i in range(1, int(math.sqrt(m)) + 1):
        if m % i == 0:
            divisors.append(i)
            divisors.append(m // i)

    # Sum over k|m, k>1
    total_cycles = 0
    for k in divisors:
        if k > 1:
            if k % 3 == 0:
                # Should not happen since m % 3 != 0
                continue

            order = get_order(3, k)
            if order is not None:
                # C(m) = sum phi(k) / ord_k(3)
                term = phi(k) / order
                total_cycles += term
            else:
                # Should indicate gcd(3, k) != 1
                return None 

    # Since C(m) must be an integer, rounding should be safe if calculations are precise
    return int(round(total_cycles))

